echo "=== reused_probe summary (trimmed) ===" && python -c "
import json
d=json.load(open('results/reused_probe_preflight_20261021_a/summary.json'))
def trim(o, depth=0):
    if depth>2: return '...'
    if isinstance(o, dict):
        return {k: trim(v, depth+1) for k,v in list(o.items())[:25]}
    if isinstance(o, list):
        return [trim(x, depth+1) for x in o[:6]] + (['...%d more'%(len(o)-6)] if len(o)>6 else [])
    s=str(o)
    return o if len(s)<300 else s[:300]+'...'
print(json.dumps(trim(d), ensure_ascii=False, indent=1)[:8000])
"

