python - <<'PY'
import json, glob, collections, statistics as st
root='results/refresh_full_20261021'
def is_read(name):
    if not name: return None
    return name.split('_')[0] in {'get','search','list','find'}
def cat(r):
    t=r['turns'][0] if r['turns'] else {}
    if not t.get('baseline_has_tool_call'): return 'no_tool'
    return 'tool_matched' if t.get('spec_used') else 'tool_mismatched'
events=[]
for p in glob.glob(root+'/records/*_refresh.json'):
    r=json.load(open(p))
    for t in r['turns']:
        specs=t.get('speculations') or []
        old=[s for s in specs if s.get('superseded')]
        new=[s for s in specs if s.get('committed')]
        if t.get('exit',{}).get('refresh_count'):
            # pair each superseded with the next non-superseded
            calls=[(s.get('call',{}).get('name'),s.get('superseded')) for s in specs]
            for i,s in enumerate(specs):
                if s.get('superseded'):
                    nxt=next((x for x in specs[i+1:] if not x.get('superseded')),None)
                    events.append({'group':r['group_id'],'split':r['split'],'turn':t.get('turn'),
                        'old':s.get('call',{}).get('name'),'new':(nxt or {}).get('call',{}).get('name'),
                        'old_read':is_read(s.get('call',{}).get('name')),
                        'new_read':is_read((nxt or {}).get('call',{}).get('name')),
                        'reward':(r.get('action_reward') or {}).get('reward'),
                        'wall':r['wall_s'],'cat':cat(r)})
print('refresh events',len(events))
c=collections.Counter((e['old_read'],e['new_read']) for e in events)
for k,v in sorted(c.items(),key=str): print(' ',k,v)
for kind in [(True,True),(True,False),(False,True),(False,False)]:
    sub=[e for e in events if (e['old_read'],e['new_read'])==kind]
    if sub: print(kind,'n',len(sub),'tasks',len(set(e['group'] for e in sub)),
                 'rewards',collections.Counter(e['reward'] for e in sub))
print('\nread->write events:')
for e in events:
    if e['old_read'] and not e['new_read']:
        print(' ',e['group'],e['cat'],e['old'],'->',e['new'],'reward',e['reward'],'wall',round(e['wall'],1))
print('\nwrite->* events:')
for e in events:
    if not e['old_read']:
        print(' ',e['group'],e['cat'],e['old'],'->',e['new'],'reward',e['reward'],'wall',round(e['wall'],1))
PY

