        return {"cot_tokens": pos, "tool_call_tokens": len(ids) - pos,
                "post_tool_call_tokens": 0, "total_decode_tokens": len(ids),
                "tool_call_closed": "</tool_call>" in (text or ""),
                "tool_call_parse_ok": self.parse_main_tool_call(text) is not None}

