import json,glob,statistics as st,collections
root='results/qwen35_refresh_full_20261102'
recs={}
for p in glob.glob(root+'/records/*.json'):
    if p.endswith('.seal'): continue
    r=json.load(open(p)); recs[(r['group_id'],r['config'])]=r
print('records',len(recs))
# spork turn cot distributions
tool=[]; notool=[]; exits=[]; exits_rem=[]; rates=[]
for (g,c),r in recs.items():
    if c!='spork': continue
    for t in r['turns']:
        cot=t.get('cot_tokens') or 0
        if t.get('baseline_has_tool_call'): tool.append(cot)
        else: notool.append(cot)
        if t.get('main_end_ms') and cot: rates.append(t['main_end_ms']/1000/cot)
print('spork tool turns',len(tool),'cot median',st.median(tool),'p25',sorted(tool)[len(tool)//4],'p75',sorted(tool)[3*len(tool)//4],'max',max(tool))
print('spork no-tool turns',len(notool),'cot median',st.median(notool) if notool else None,'p75',sorted(notool)[3*len(notool)//4] if notool else None,'max',max(notool) if notool else None)
print('decode s/token median',round(st.median(rates),3) if rates else None)
# exits in eta/refresh
for cfg in ('eta','refresh'):
    n=0; rem=[]; cuts=[]
    for (g,c),r in recs.items():
        if c!=cfg: continue
        for t in r['turns']:
            ex=t.get('exit') or {}
            if ex.get('fired'):
                n+=1; cuts.append(ex.get('cut_tokens'))
                sp=recs.get((g,'spork'))
                if sp:
                    for sturn in sp['turns']:
                        if sturn.get('turn')==t.get('turn'):
                            rem.append((sturn.get('cot_tokens') or 0)-(ex.get('cut_tokens') or 0))
    print(cfg,'exits',n,'cut median',st.median(cuts) if cuts else None,'remaining median',st.median(rem) if rem else None,'remaining p75',sorted(rem)[3*len(rem)//4] if rem else None)
# failure summary
d=json.load(open(root+'/summary.json'))
print('failures n',len(d.get('failures') or []))
print(collections.Counter(f['config'] for f in (d.get('failures') or [])))
print('quality_by_category',json.dumps(d.get('quality_by_category'),ensure_ascii=False)[:1200])
