python - <<'PY'
import json,glob,collections
root='results/qwen32_guard_smoke_20261104_a/records'
recs={}
for p in glob.glob(root+'/*.json'):
    d=json.load(open(p)); recs[(d['group_id'],d['method'])]=d
def last_answer(r):
    for t in reversed(r['turns']):
        if not t.get('baseline_has_tool_call'):
            return (t.get('baseline_text') or '').rsplit('</think>',1)[-1].strip()
    return None
for g in sorted({g for g,m in recs}):
    print('==',g)
    for m in ('spork','eta','refresh','off'):
        r=recs.get((g,m))
        if not r: continue
        ex=[(t.get('turn'),(t.get('exit') or {})) for t in r['turns']]
        refreshes=sum((e.get('refresh_count') or 0) for _,e in ex)
        blocked=sum((e.get('refresh_blocked') or 0) for _,e in ex)
        rb=[e.get('rollback_reason') for _,e in ex if e.get('rolled_back')]
        print(f'  {m:8} wall {r["wall_s"]:7.1f} turns {len(r["turns"])} exits {sum(1 for _,e in ex if e.get("fired"))} ref {refreshes} blocked {blocked} rb {rb}')
    # final answer equality vs spork
    s=recs.get((g,'spork')); sa=last_answer(s) if s else None
    for m in ('eta','refresh','off'):
        r=recs.get((g,m)); a=last_answer(r) if r else None
        print(f'    {m:8} same_final_answer={a==sa} ans_head={repr((a or "")[:60])}')
PY

